   }
   .footer_wrap--paymentlogos .paymentlogos--rightwrap img {
   margin-left: 10px;
   }
   .footer-logo-wrpr {
   display: flex;
   align-items: center;
   justify-content: space-between;
   }
   @media (min-width: 992px) {
   .footer-terms-logos {
   flex: 1 1 70%;
   }
   .footer-payment-logos {
   flex: 1 1 30%;
   }
   }
   @media only screen and (max-width: 1200px) and (min-width: 993px) {
   .footer-terms-logos {
   display: block;
   width: 100%;
   }
   .footer-terms-logos {
   flex: 1 1 55%;
   }
   .footer_wrap--paymentlogos .paymentlogos--rightwrap img {
   max-width: 110px;
   }
   }
   @media only screen and (max-width: 992px) {
   .footer-payment-logos {
   width: 100%;
   }
   .footer_wrap--paymentlogos .paymentlogos--leftwrap {
   margin-top: 20px;
   }
   }
   @media (max-width: 767px) {
   .footer-logo-wrpr {
   flex-direction: column-reverse;
   }
   }
   @media (max-width: 896px) and (orientation: landscape),
   (max-width: 767px) and (orientation: portrait) {
   .footer_wrap--paymentlogos .paymentlogos--rightwrap img {
   margin-left: 5px;
   max-width: 110px;
   }
   }
</style>
